"use client";

import { useState } from "react";
import { ChevronDown, Thermometer, Droplets, Wind, Weight } from "lucide-react";
import { BIN_INFO } from "@/app/data/mockSensorData";

const SENSORS = [
  {
    icon: Thermometer,
    name: "Temperature sensor",
    model: "DS18B20 waterproof probe",
    purpose: "Measures compost temperature.",
    detail:
      "Temperature provides an indirect indication of microbial activity. During active composting, heat is generated by microbial metabolism. However, temperature alone does not directly measure microbial populations or species diversity.",
  },
  {
    icon: Droplets,
    name: "Moisture sensor",
    model: "Capacitive soil moisture v2.0",
    purpose: "Measures moisture level in the compost.",
    detail:
      "Optimal moisture (50–70%) supports microbial activity and decomposition. Too dry (<40%) inhibits microbial growth; too wet (>80%) can restrict oxygen and promote anaerobic conditions.",
  },
  {
    icon: Wind,
    name: "Gas sensors",
    model: "MH-Z19B (CO₂) · MQ-4 (CH₄) · MQ-137 (NH₃) · MQ-136 (H₂S)",
    purpose: "Monitor gases associated with composting and decomposition.",
    detail:
      "CO₂ indicates microbial respiration. CH₄ and H₂S may indicate anaerobic conditions (insufficient oxygen). NH₃ may indicate nitrogen-rich material decomposition or C/N ratio imbalance. Readings are monitoring indicators and should be interpreted in context.",
  },
  {
    icon: Weight,
    name: "Load cell",
    model: "10 kg load cell + HX711 amplifier",
    purpose: "Measures the mass of the compost bin contents.",
    detail:
      "Weight reduction over time indicates material loss through decomposition (CO₂ and water vapour release). It is a useful progress indicator but does NOT alone confirm that the compost is mature or pathogen-free.",
  },
] as const;

const DEVICE = [
  { label: "Bin", value: `${BIN_INFO.id} · ${BIN_INFO.capacityKg} kg capacity` },
  { label: "Controller", value: BIN_INFO.device },
  { label: "Firmware", value: BIN_INFO.firmware },
  { label: "Sample interval", value: BIN_INFO.sampleInterval },
];

export default function SensorInfo() {
  const [open, setOpen] = useState(false);

  return (
    <div className="rounded-xl border border-line bg-card overflow-hidden">
      <button
        id="sensor-info-toggle"
        onClick={() => setOpen((p) => !p)}
        aria-expanded={open}
        className="w-full flex items-center justify-between gap-3 p-5 text-left hover:bg-subtle transition-colors"
      >
        <div>
          <h3 className="text-sm font-semibold text-fg">About the sensors</h3>
          <p className="text-xs text-muted mt-0.5">Hardware and what each monitored parameter means</p>
        </div>
        <ChevronDown className={`w-4 h-4 text-muted transition-transform ${open ? "rotate-180" : ""}`} />
      </button>

      {open && (
        <div className="border-t border-line p-5 fade-in">
          <dl className="grid grid-cols-2 md:grid-cols-4 gap-4 pb-5 mb-5 border-b border-line">
            {DEVICE.map((d) => (
              <div key={d.label}>
                <dt className="text-xs text-muted">{d.label}</dt>
                <dd className="text-sm text-fg mt-0.5">{d.value}</dd>
              </div>
            ))}
          </dl>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-x-8 gap-y-6">
            {SENSORS.map((sensor) => (
              <div key={sensor.name} className="flex gap-3">
                <sensor.icon className="w-4 h-4 text-muted mt-0.5 shrink-0" />
                <div>
                  <p className="text-sm font-medium text-fg">{sensor.name}</p>
                  <p className="text-xs text-faint mt-0.5">{sensor.model}</p>
                  <p className="text-sm text-fg mt-2">{sensor.purpose}</p>
                  <p className="text-xs text-muted leading-relaxed mt-1">{sensor.detail}</p>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}
